grid=[[8,8,8,8,6,8,8],[8,6,8,8,8,8,8],[8,8,8,8,8,8,6],[8,8,8,8,8,8,8],[8,8,8,8,8,8,8],[8,8,8,8,6,8,8],[8,6,8,8,8,8,6],[8,6,8,6,8,8,6]]
marker=6; bridge=3
out=[r[:] for r in grid]
for r,row in enumerate(grid):
    cols=[c for c,v in enumerate(row) if v==marker]
    for a,b in zip(cols,cols[1:]):
        for c in range(a+1,b): out[r][c]=bridge
for c in range(len(grid[0])):
    rows=[r for r in range(len(grid)) if grid[r][c]==marker]
    for a,b in zip(rows,rows[1:]):
        for r in range(a+1,b): out[r][c]=bridge
assert len(out)==8 and all(len(r)==7 for r in out) and set(sum(out,[])) <= {3,6,8}
import json
print(json.dumps(out,separators=(',',':')))
